package dev.leapfrog.block;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import dev.leapfrog.Leapfrog;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import net.minecraft.resources.Identifier;
import org.jspecify.annotations.Nullable;

/**
 * Hardness, tool requirement and tool tags of the 26.x blocks (generated by tools/MiningDump.java).
 * ViaBackwards doesn't send tags for these blocks, so the client needs its own copy.
 */
public final class FutureMining {
    public record Mining(float hardness, boolean requiresTool, Set<Identifier> tags) {}

    private static @Nullable Map<String, Mining> data;

    private FutureMining() {}

    public static synchronized @Nullable Mining get(String block) {
        if (data == null) data = load();
        return data.get(block);
    }

    private static Map<String, Mining> load() {
        Map<String, Mining> out = new HashMap<>();
        try (InputStream in = FutureMining.class.getResourceAsStream("/assets/leapfrog/future_block_mining.json")) {
            if (in == null) {
                Leapfrog.LOG.error("future_block_mining.json missing: 26.x blocks will use a default hardness");
                return out;
            }
            JsonObject root = JsonParser.parseReader(new InputStreamReader(in, StandardCharsets.UTF_8)).getAsJsonObject();
            for (Map.Entry<String, JsonElement> e : root.entrySet()) {
                JsonObject o = e.getValue().getAsJsonObject();
                Set<Identifier> tags = new HashSet<>();
                for (JsonElement t : o.getAsJsonArray("tags")) tags.add(Identifier.parse(t.getAsString()));
                out.put(e.getKey(), new Mining(o.get("hardness").getAsFloat(), o.get("requiresTool").getAsBoolean(), Set.copyOf(tags)));
            }
        } catch (Exception ex) {
            Leapfrog.LOG.error("Could not read 26.x mining data", ex);
        }
        return out;
    }
}
